/**
 * @param {Object|Array} obj1
 * @param {Object|Array} obj2
 * @return {Object|Array}
 */
function objDiff(obj1, obj2) {
    const isObject = v => v !== null && typeof v === "object";

    // Primitives (or null): equal -> no difference, else the pair
    if (!isObject(obj1) || !isObject(obj2)) {
        return obj1 === obj2 ? {} : [obj1, obj2];
    }

    // Different kinds of containers (array vs. object): report the pair
    if (Array.isArray(obj1) !== Array.isArray(obj2)) {
        return [obj1, obj2];
    }

    // Both arrays or both objects: compare only keys/indices present in both
    const diff = {};
    for (const key of Object.keys(obj1)) {
        if (key in obj2) {
            const sub = objDiff(obj1[key], obj2[key]);
            // Keep it if it's a [v1, v2] pair or a non-empty nested diff
            if (Array.isArray(sub) || Object.keys(sub).length > 0) {
                diff[key] = sub;
            }
        }
    }
    return diff;
}
